terraform {
  required_providers {
    aci = {
      source  = "CiscoDevNet/aci"
      version = "~> 2.0"
    }
  }
}

provider "aci" {
  url      = "https://apic.example.com"
  username = "terraform"
  password = var.apic_password   # supplied from a secret store
}

resource "aci_tenant" "prod" {
  name = "PROD"
}

resource "aci_vrf" "prod_vrf" {
  tenant_dn = aci_tenant.prod.id
  name      = "PROD-VRF"
}

resource "aci_bridge_domain" "web" {
  tenant_dn          = aci_tenant.prod.id
  name               = "WEB-BD"
  relation_fv_rs_ctx = aci_vrf.prod_vrf.id
}

